import { useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from '@/components/ui/form';
import colors from '../../data/carsColors';
import TextInputForm from '@/components/forms/TextInputForm';
import { cn } from '@/lib/utils';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import CalendarIcon from '@/components/icons/CalendarIcon';

const CarColor = () => {
    const { control } = useFormContext();
    const [colorPopupOpen, setColorPopupOpen] = useState(false);

    return (
        <div className="mt-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormField
                    control={control}
                    name="color"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                                لون السيارة
                            </FormLabel>
                            <FormControl>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setColorPopupOpen(true)}
                                    className="pe-3 text-start font-medium flex flex-row justify-between w-full"
                                >
                                    {field.value ? (
                                        <span className="flex items-center gap-2">
                                            <span
                                                className="w-6 h-6 rounded border border-white-blue-300 shrink-0"
                                                style={{
                                                    backgroundColor: field.value,
                                                    boxShadow:
                                                        'inset 0 1px 0 rgba(255,255,255,0.4), 0 1px 2px rgba(0,0,0,0.1)',
                                                }}
                                            />
                                            {field.value}
                                        </span>
                                    ) : (
                                        <span className="text-white-blue-600">اختر لون السيارة</span>
                                    )}
                                    <CalendarIcon width="24" height="24" className="text-white-blue-600" />
                                </Button>
                            </FormControl>
                            <FormMessage />

                            <Dialog open={colorPopupOpen} onOpenChange={(open) => !open && setColorPopupOpen(false)}>
                                <div
                                    className={cn('fixed inset-0 bg-black/50 z-[50]', {
                                        '!hidden': !colorPopupOpen,
                                    })}
                                />
                                <DialogContent
                                    showCloseButton
                                    className="z-[51] max-w-sm rounded-lg p-6 bg-white-blue-50 font-cairo mt-8"
                                >
                                    <DialogHeader className="flex flex-col items-start mb-4 mt-4">
                                        <h3 className="text-[22px] font-bold text-primery-blue-500">
                                            اختر لون السيارة
                                        </h3>
                                        <div className="w-full border-b border-[#D1D1D1] mt-2" />
                                    </DialogHeader>
                                    <div className="grid grid-cols-[repeat(auto-fill,minmax(44px,1fr))] gap-3 p-1">
                                        {colors.map(({ name, value }) => (
                                            <button
                                                key={value}
                                                type="button"
                                                onClick={() => {
                                                    field.onChange(value);
                                                    setColorPopupOpen(false);
                                                }}
                                                className={cn(
                                                    'relative w-11 h-11 rounded-md border-2 overflow-hidden transition-all hover:shadow-md hover:scale-105',
                                                    {
                                                        'border-primery-blue-500 ring-2 ring-primery-blue-200':
                                                            field.value === value,
                                                        'border-transparent': field.value !== value,
                                                    },
                                                )}
                                                style={{
                                                    backgroundColor: value,
                                                    boxShadow:
                                                        'inset 0 1px 0 rgba(255,255,255,0.45), inset -1px -1px 0 rgba(255,255,255,0.15), 0 1px 3px rgba(0,0,0,0.12)',
                                                    backgroundImage: `linear-gradient(135deg, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0.12) 35%, transparent 60%), linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.06) 100%)`,
                                                }}
                                            />
                                        ))}
                                    </div>
                                </DialogContent>
                            </Dialog>
                        </FormItem>
                    )}
                />

                <TextInputForm
                    name="next_maintainance_mile"
                    type="number"
                    label="عدد الكيلومتر للصيانة القادمة"
                    placeholder="أدخل عدد الكيلومتر للصيانة القادمة"
                />
            </div>
        </div>
    );
};

export default CarColor;
