import { useFormContext } from 'react-hook-form';
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DateInputForm } from '@/components/forms/DateInputForm';

export default function ExtraInfo() {
    const { control } = useFormContext();

    return (
        <div className="mt-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormField
                    control={control}
                    name="status"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                                حالة السيارة
                            </FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                                <FormControl>
                                    <SelectTrigger>
                                        <SelectValue
                                            placeholder={<span style={{ color: '#D1D1D1' }}>أدخل حالة السيارة</span>}
                                        />
                                    </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                    {[
                                        { label: 'متاحه', value: 'available' },
                                        { label: 'غير متاحه', value: 'not available' },
                                    ].map((el) => (
                                        <SelectItem key={el.value} value={el.value} className="font-cairo">
                                            {el.label}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <DateInputForm
                    name="license_expiry_date"
                    disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                    label="تاريخ إنتهاء الرخصة"
                    placeholder="ادخل تاريخ إنتهاء الرخصة"
                />
            </div>
        </div>
    );
}
