import { useFormContext } from 'react-hook-form';
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useCallback, useEffect, useState } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { Brand, Car, Model } from '@/types/cars.types';
import CalendarIcon from '@/components/icons/CalendarIcon';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { cn } from '@/lib/utils';
import { Input } from '@/components/ui/input';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import AddIcon from '@/components/icons/AddIcon';
import { toast } from 'sonner';

interface Props {
    car?: Car;
}

export default function VehicleInfo({ car }: Props) {
    const { control, setValue } = useFormContext();
    const [models, setModels] = useState<Model[]>([]);
    const [brands, setBrands] = useState<Brand[]>([]);
    const [selectedBrand, setSelectedBrand] = useState<number | null>(null);
    const currentYear = new Date().getFullYear();
    const yearOptions = Array.from({ length: currentYear + 20 - 1990 + 1 }, (_, i) => 1990 + i);
    const [brandError, setBrandError] = useState<string | null>(null);
    const [modelError, setModelError] = useState<string | null>(null);
    const [addPopupOpen, setAddPopupOpen] = useState(false);
    const [newBrandName, setNewBrandName] = useState('');
    const [newModelName, setNewModelName] = useState('');
    const [newMakeYear, setNewMakeYear] = useState<number>(currentYear);
    const [addLoading, setAddLoading] = useState(false);

    const fetchBrands = useCallback(async () => {
        try {
            const response = await apiGet({ endpoint: endpoints.brands.list });
            setBrands(response.data.data);
            setBrandError(null);
        } catch (error) {
            setBrandError('Error fetching brands. Please try again later.');
        }
    }, []);

    useEffect(() => {
        fetchBrands();
    }, [fetchBrands]);

    useEffect(() => {
        const fetchModels = async (brandId: number) => {
            try {
                const response = await apiGet({ endpoint: `${endpoints.brands.show}/${brandId}` });
                setModels(response.data.data.models);
                setModelError(null);
            } catch (error) {
                setModelError('Error fetching models. Please try again later.');
            }
        };

        if (selectedBrand) {
            fetchModels(selectedBrand);
        } else {
            setModels([]);
            setModelError(null);
        }
    }, [selectedBrand]);

    useEffect(() => {
        if (brands.length > 0 && car?.vehicle_brand_id) {
            setValue('vehicle_brand_id', car?.vehicle_brand_id);
            handleSelectedBrand(car?.vehicle_brand_id);
        }
    }, [brands]);

    useEffect(() => {
        if (models.length > 0 && car?.vehicle_model_id) {
            setValue('vehicle_model_id', car?.vehicle_model_id);
        }
    }, [models]);

    const handleSelectedBrand = (id: number) => {
        const brand = brands.find((brand) => brand.id === id);
        if (brand) {
            setSelectedBrand(brand.id);
            if (car) {
                setValue('vehicle_model_id', car?.vehicle_model_id);
            } else {
                setValue('vehicle_model_id', undefined);
            }
            setModelError(null);
        }
    };

    const handleAddBrandModelYear = async () => {
        if (!newBrandName.trim() || !newModelName.trim()) {
            toast.error('الرجاء إدخال الماركة والموديل');
            return;
        }
        setAddLoading(true);
        try {
            const res = await apiPost({
                endpoint: endpoints.brands.brandAndModelCreate,
                body: {
                    brand_name: newBrandName.trim(),
                    model_name: newModelName.trim(),
                    year_of_creation: newMakeYear,
                },
            });
            const data = res?.data?.data;
            const brandId = data?.vehicle_brand_id ?? data?.brand_id ?? data?.brand?.id;
            const modelId = data?.vehicle_model_id ?? data?.model_id ?? data?.model?.id;

            if (brandId != null && modelId != null) {
                setValue('vehicle_brand_id', brandId);
                setValue('vehicle_model_id', modelId);
                setValue('make_year', newMakeYear);
                setSelectedBrand(brandId);
                await fetchBrands();
                const modelsRes = await apiGet({ endpoint: `${endpoints.brands.show}/${brandId}` });
                setModels(modelsRes?.data?.data?.models ?? []);
                setNewBrandName('');
                setNewModelName('');
                setNewMakeYear(currentYear);
                setAddPopupOpen(false);
                toast.success('تمت إضافة الماركة والموديل وسنة الصنع');
            } else {
                toast.error('لم يتم إرجاع معرف الماركة أو الموديل من الخادم');
            }
        } catch (error: any) {
            const msg = error?.response?.data?.msg || 'حدث خطأ. يرجى المحاولة مرة أخرى.';
            toast.error(msg);
        } finally {
            setAddLoading(false);
        }
    };

    return (
        <div className="mt-6 pt-4 border-t border-t-white-blue-500">
            <div className="flex flex-col xl:flex-row xl:items-end gap-4">
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 flex-1">
                    <FormField
                        control={control}
                        name="vehicle_brand_id"
                        render={({ field }) => (
                            <FormItem>
                                <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                                    الماركة
                                </FormLabel>
                                <Select
                                    onValueChange={(value) => {
                                        field.onChange(Number(value));
                                        handleSelectedBrand(Number(value));
                                        setBrandError(null);
                                    }}
                                    defaultValue={field.value}
                                    value={car && String(field.value)}
                                >
                                    <FormControl>
                                        <SelectTrigger>
                                            <SelectValue
                                                placeholder={<span style={{ color: '#D1D1D1' }}>اختر الماركة</span>}
                                            />
                                        </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                        {brands.map((brand) => (
                                            <SelectItem key={brand.id} value={String(brand.id)}>
                                                {brand.name}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                                <FormMessage>{brandError}</FormMessage>
                            </FormItem>
                        )}
                    />

                    <FormField
                        control={control}
                        name="vehicle_model_id"
                        render={({ field }) => (
                            <FormItem>
                                <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                                    الموديل
                                </FormLabel>
                                <Select
                                    onValueChange={(value) => field.onChange(Number(value))}
                                    defaultValue={field.value}
                                    disabled={!selectedBrand}
                                    value={car && String(field.value)}
                                >
                                    <FormControl>
                                        <SelectTrigger>
                                            <SelectValue
                                                placeholder={<span style={{ color: '#D1D1D1' }}>اختر الموديل</span>}
                                            />
                                        </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                        {models.map((model) => (
                                            <SelectItem key={model.id} value={String(model.id)}>
                                                {model.name}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                                <FormMessage>{modelError}</FormMessage>
                            </FormItem>
                        )}
                    />

                    <FormField
                        control={control}
                        name="make_year"
                        render={({ field }) => (
                            <FormItem className="flex flex-col justify-start">
                                <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                                    سنة الصنع
                                </FormLabel>
                                <Select
                                    onValueChange={(value) => field.onChange(Number(value))}
                                    value={car && String(field.value)}
                                >
                                    <FormControl>
                                        <SelectTrigger
                                            className="w-full text-black"
                                            Icon={
                                                <CalendarIcon width="24" height="24" className="text-white-blue-600" />
                                            }
                                        >
                                            <SelectValue
                                                placeholder={<span style={{ color: '#D1D1D1' }}>أدخل سنة الصنع</span>}
                                            />
                                        </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                        {yearOptions.map((y) => (
                                            <SelectItem key={y} value={String(y)}>
                                                {y}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                                <FormMessage />
                            </FormItem>
                        )}
                    />
                </div>
                <button
                    type="button"
                    onClick={() => setAddPopupOpen(true)}
                    className="flex items-center justify-center gap-2 rounded-lg border border-primery-blue-50 bg-primery-blue-50 px-4 py-3 text-primery-blue-500 font-cairo font-semibold hover:bg-primery-blue-100 transition-colors"
                >
                    <AddIcon />
                    <span>إضافة</span>
                </button>
            </div>

            <Dialog open={addPopupOpen} onOpenChange={(open) => !open && setAddPopupOpen(false)}>
                <div className={cn('fixed inset-0 bg-black/50 z-[50]', { '!hidden': !addPopupOpen })} />
                <DialogContent showCloseButton className="z-[51] max-w-md rounded-lg p-8 bg-white-blue-50 font-cairo">
                    {/* <DialogHeader className="flex flex-col items-start mb-4">
                        <h3 className="text-[22px] font-bold text-primery-blue-500">إضافة</h3>
                        <div className="w-full border-b border-[#D1D1D1] mt-2" />
                    </DialogHeader> */}
                    <div className="grid gap-4 pt-4">
                        {/* brand */}
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-sm">الماركة</label>
                            <Input
                                value={newBrandName}
                                onChange={(e) => setNewBrandName(e.target.value)}
                                placeholder="اسم الماركة"
                                className="font-cairo"
                            />
                        </div>

                        {/* model */}
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-sm">الموديل</label>
                            <Input
                                value={newModelName}
                                onChange={(e) => setNewModelName(e.target.value)}
                                placeholder="اسم الموديل"
                                className="font-cairo"
                            />
                        </div>

                        {/* make year */}
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-sm">سنة الصنع</label>
                            <Select value={String(newMakeYear)} onValueChange={(v) => setNewMakeYear(Number(v))}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent className="z-[100]">
                                    {yearOptions.map((y) => (
                                        <SelectItem key={y} value={String(y)}>
                                            {y}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        {/* add buttons */}
                        <div className="flex gap-3 pt-2">
                            <PrimaryButton
                                type="button"
                                disabled={addLoading}
                                onClick={handleAddBrandModelYear}
                                className="flex-1"
                            >
                                {addLoading ? 'جاري الحفظ...' : 'إضافة'}
                            </PrimaryButton>
                            <SecondaryButton type="button" onClick={() => setAddPopupOpen(false)} className="flex-1">
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
